class Solution {
    static int postIndex = 0;

    static boolean checktree(int preorder[], int inorder[], int postorder[], int N) {
        int generated[] = new int[N];
        build(preorder, inorder, generated, 0, N-1, 0, N-1);

        for(int i = 0; i < N; i++){
            if(generated[i] != postorder[i])
                return false;
        }
        return true;
    }

    static void build(int pre[], int in[], int gen[], int preStart, int preEnd, int inStart, int inEnd){
        if(preStart > preEnd || inStart > inEnd)
            return;

        int root = pre[preStart];
        int index = inStart;
        while(in[index] != root)
            index++;

        int leftSize = index - inStart;

        build(pre, in, gen, preStart+1, preStart+leftSize, inStart, index-1);
        build(pre, in, gen, preStart+leftSize+1, preEnd, index+1, inEnd);

        gen[postIndex++] = root;
    }
}
